UPDATE TB_CTR_MED_CHECK
   SET CHECK_STAT_CD = '10', OTHER_COUNT = #{otherCount}, CHECKED_DT = #{now}, CHECK_EMP_ID = #{empId}, LAST_ERROR = NULL
 WHERE CONTRACT_NO = #{contractNo}

UPDATE TB_CTR_MED_CHECK
   SET CHECK_STAT_CD = '80', OTHER_COUNT = NULL, CHECKED_DT = #{now}, CHECK_EMP_ID = #{empId}, LAST_ERROR = #{lastError}
 WHERE CONTRACT_NO = #{contractNo}

UPDATE TB_CLM_MED_ITEM
   SET COVERED_ASSESSED = #{coveredAssessed}, NON_COVERED_ASSESSED = #{nonCoveredAssessed}, COVERED_DEDUCT = #{coveredDeduct},
       COVERED_PAY = #{coveredPay}, NON_COVERED_DEDUCT = #{nonCoveredDeduct}, NON_COVERED_PAY = #{nonCoveredPay}
 WHERE CLM_NO = #{clmNo} AND SEQ = #{seq}

mapper.select:
SELECT CVRG_CD, INSURER_CD, POLICY_NO, (INSURER_CD = #{ownInsurerCd}) AS OWN, LIABILITY_AMT, SHARE_AMT
  FROM TB_CLM_MED_SHARE WHERE CLM_NO = #{clmNo}
 ORDER BY CVRG_CD, CASE WHEN INSURER_CD = #{ownInsurerCd} THEN 0 ELSE 1 END, INSURER_CD, POLICY_NO
